import 'package:flutter/material.dart';import 'glass_card.dart';class FuturisticPeriodSelector extends StatelessWidget{final List<String> items;final int selected;final ValueChanged<int> onChanged;final Color color;const FuturisticPeriodSelector({super.key,this.items=const['24 ساعة','7 أيام','30 يوم'],required this.selected,required this.onChanged,this.color=const Color(0xFF00E5A0)});@override Widget build(BuildContext c)=>GlassCard(padding:const EdgeInsets.all(5),child:Row(children:[for(int i=0;i<items.length;i++)Expanded(child:GestureDetector(onTap:()=>onChanged(i),child:AnimatedContainer(duration:const Duration(milliseconds:250),padding:const EdgeInsets.symmetric(vertical:10),decoration:BoxDecoration(color:i==selected?color.withOpacity(.18):Colors.transparent,borderRadius:BorderRadius.circular(16)),child:Text(items[i],textAlign:TextAlign.center,style:TextStyle(color:i==selected?Colors.white:Colors.white54,fontWeight:FontWeight.w700)))))]));}